import re

HDR = re.compile(r'^Port\s+Name\s+Status\s+Vlan\s+Duplex\s+Speed\s+Type')
PROMPT = re.compile(r'^\S+[#>]')

def cut(line, cols):
    rec = {}
    n = len(cols)
    for i in range(n):
        name, start = cols[i]
        end = cols[i + 1][1] if i + 1 < n else None
        s = start
        while s > 0 and s < len(line) and line[s - 1] != ' ' and line[s] != ' ':
            s -= 1
        if end is not None:
            e = end
            while e > 0 and e < len(line) and line[e - 1] != ' ' and line[e] != ' ':
                e -= 1
            val = line[s:e]
        else:
            val = line[s:]
        rec[name] = val.strip()
    return rec

def parse(lines):
    skip = []
    used = []
    recs = []
    cols = None
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if HDR.match(line):
            cols = [(m.group(0), m.start()) for m in re.finditer(r'\S+', line)]
            used.append(i)
            continue
        if PROMPT.match(line) or cols is None:
            skip.append(i)
            continue
        if line[:1] == ' ':
            skip.append(i)
            continue
        recs.append(cut(line, cols))
        used.append(i)
    blocks = []
    if recs:
        blocks.append({'name': 'interfaces', 'kind': 'table', 'lines': used, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
